// Agrupa a los candidatos por cercanía (grupo calculado en la base) → 1 consulta de pronóstico por grupo
const cfg = $('Configuración').first().json.cfg;
const grupos = new Map();

for (const { json: u } of $input.all()) {
  if (!u.usuario_id) continue;
  if (!grupos.has(u.grupo)) grupos.set(u.grupo, { grupo: u.grupo, lat: u.grupo_lat, lon: u.grupo_lon, usuarios: [] });
  grupos.get(u.grupo).usuarios.push(u);
}

const base = String(cfg.lluvia_api_url || '').replace(/\/+$/, '');
const fuente = cfg.lluvia_fuente === 'open-meteo' ? 'open-meteo' : 'iagro';

return [...grupos.values()].map((g) => ({
  json: {
    ...g,
    fuente,
    url: fuente === 'open-meteo'
      ? `https://api.open-meteo.com/v1/forecast?latitude=${g.lat}&longitude=${g.lon}&hourly=precipitation_probability,precipitation&timezone=${encodeURIComponent(cfg.zona_horaria || 'America/La_Paz')}&forecast_days=3`
      : `${base}/forecast/hourly?lat=${g.lat}&lon=${g.lon}`,
  },
}));

// Para cada usuario: busca su PRÓXIMA lluvia (primera hora que supera el umbral) en el pronóstico de su grupo.
// - Devuelve un item por usuario (se guarda en bot_clima.pronosticos → el panel muestra "faltan X h").
// - enviar = true cuando la lluvia está a N horas o menos (por defecto 24) y la base permite enviarle (puede_enviar).
const cfg = $('Configuración').first().json.cfg;
const grupos = $('Agrupar por zona').all();
const tz = cfg.zona_horaria || 'America/La_Paz';
const umbral = Number(cfg.lluvia_umbral ?? 60);
const mmMinimo = Number(cfg.lluvia_mm_minimo ?? 0);
const horas = Number(cfg.lluvia_horas_anticipacion ?? 24);
const mmFuerte = Number(cfg.lluvia_fuerte_mm ?? 20);   // para quien eligió "Solo lluvias fuertes"

const ahora = DateTime.now().setZone(tz);
const desde = ahora.startOf('hour');            // la hora en curso cuenta como "lloviendo ahora"
const limite = ahora.plus({ hours: horas });
const DIAS = ['', 'lunes', 'martes', 'miércoles', 'jueves', 'viernes', 'sábado', 'domingo'];

const num = (v) => { const n = parseFloat(String(v ?? '').replace(',', '.')); return Number.isFinite(n) ? n : null; };

function cuandoTexto(dt) {
  const d = Math.round(dt.startOf('day').diff(ahora.startOf('day'), 'days').days);
  return `${d === 0 ? 'hoy' : d === 1 ? 'mañana' : DIAS[dt.weekday]} ${dt.toFormat('dd/LL')} a las ${dt.toFormat('HH:mm')}`;
}

/** API IAGRO: data[].fecha (dd/mm/aaaa) + horarios[].h ("15:00" o "15"), rp = probabilidad, sr = mm */
function horasIagro(resp) {
  const out = [];
  for (const dia of Array.isArray(resp?.data) ? resp.data : []) {
    const f = String(dia.fecha ?? '').trim();
    let base = DateTime.fromFormat(f, 'd/L/yyyy', { zone: tz });
    if (!base.isValid) base = DateTime.fromISO(f.slice(0, 10), { zone: tz });
    if (!base.isValid) continue;
    for (const x of dia.horarios || []) {
      const m = String(x.h ?? x.hora ?? '').match(/(\d{1,2})(?::\d{2})?\s*$/);
      if (!m) continue;
      out.push({ dt: base.set({ hour: Number(m[1]) }), prob: num(x.rp), mm: num(x.sr) ?? 0 });
    }
  }
  return out;
}

/** Open-Meteo: hourly.time en hora local (se pidió con timezone) */
function horasOpenMeteo(resp) {
  const h = resp?.hourly || {};
  return (h.time || []).map((t, i) => ({
    dt: DateTime.fromISO(t, { zone: tz }), prob: num(h.precipitation_probability?.[i]), mm: num(h.precipitation?.[i]) ?? 0,
  }));
}

const salida = [];
$input.all().forEach((item, i) => {
  const g = grupos[i]?.json;
  if (!g) return;
  const resp = item.json;

  let lista = [];
  let error = null;
  if (resp?.error) error = String(resp.error.message || resp.error).slice(0, 300);
  else {
    lista = (g.fuente === 'open-meteo' ? horasOpenMeteo(resp) : horasIagro(resp))
      .filter((x) => x.dt.isValid && x.dt >= desde && x.prob != null)
      .sort((a, b) => a.dt.toMillis() - b.dt.toMillis());
    if (!lista.length) error = 'El pronóstico no trae horas futuras';
  }

  const llueve = (x) => x.prob > umbral && x.mm >= mmMinimo;
  const proxima = lista.find(llueve) || null;
  const objetivo = lista.find((x) => llueve(x) && x.dt > ahora && x.dt <= limite) || null;  // la que se avisa
  const horizonte = lista.length ? lista[lista.length - 1].dt : null;

  for (const u of g.usuarios) {
    // Quien eligió "Solo lluvias fuertes": solo si la lluvia que viene trae al menos mmFuerte (suma del evento)
    const mmEvento = objetivo ? lista.filter((x) => x.dt >= objetivo.dt && x.dt <= objetivo.dt.plus({ hours: 12 })).reduce((s, x) => s + (x.mm || 0), 0) : 0;
    const fuerteOk = !u.solo_fuertes || mmEvento >= mmFuerte;
    const enviar = Boolean(objetivo && u.puede_enviar && fuerteOk);
    const base = {
      usuario_id: u.usuario_id,
      telefono: u.telefono,
      nombre: u.nombre || '',
      chatwoot_contact_id: u.chatwoot_contact_id || null,
      enviar,
      motivo: u.motivo || (objetivo && !fuerteOk ? 'no es fuerte' : null),
      fuente: g.fuente,
      error,
      proxima_lluvia: proxima ? proxima.dt.toISO() : null,
      probabilidad: proxima ? Math.round(proxima.prob) : null,
      mm: proxima ? proxima.mm : null,
      horizonte_hasta: horizonte ? horizonte.toISO() : null,
    };
    if (!enviar) { salida.push({ json: base }); continue; }

    // Siempre la plantilla aprobada por Meta: trae los botones
    // "Pronóstico 7 días" · "¿A qué hora llueve?" · "Dejar de recibir" (así se mide quién responde)
    const saludo = String(cfg.lluvia_saludo || 'Agricultor').trim();
    const campo = String(u.nombre || u.zona || 'tu campo').trim();
    const prob = Math.round(objetivo.prob);
    const mm = objetivo.mm >= 1 ? ` (unos *${Math.round(objetivo.mm)} mm*)` : '';
    const pronostico = `*${cuandoTexto(objetivo.dt)}* hay *${prob}%* de probabilidad de lluvia${mm}`;
    salida.push({
      json: {
        ...base,
        probabilidad_alerta: prob,
        hora_pronostico: objetivo.dt.toISO(),
        usar_plantilla: true,
        // Mismo texto que la plantilla {{1}} {{2}} {{3}}: así se ve igual en Chatwoot y en el panel
        contenido: `Hola ${saludo} 👋\n\n🌧️ Aviso de lluvia para *${campo}*: según el pronóstico, ${pronostico}.\n\n_Toca una opción para continuar._`,
        plantilla: {
          nombre: cfg.plantilla_lluvia || 'notificacion_pronostico',
          idioma: cfg.plantilla_idioma || 'es',
          parametros: [saludo, campo, pronostico],
        },
      },
    });
  }
});

return salida;

// Une los datos de la alerta con el resultado del envío (sub-flujo "Enviar WhatsApp")
const a = $('¿Enviar alerta?').item.json;
const r = $json;
return {
  json: {
    usuario_id: String(a.usuario_id),
    probabilidad: String(a.probabilidad_alerta),
    hora_pronostico: a.hora_pronostico,
    conversation_id: r.conversation_id ? String(r.conversation_id) : '',
    message_id: r.message_id ? String(r.message_id) : '',
    contact_id: r.contact_id ? String(r.contact_id) : '',
    error: r.ok ? '' : String(r.error || 'Error desconocido al enviar').slice(0, 500),
  },
};

// Junta la próxima lluvia de todos los usuarios en un solo JSON → bot_clima.guardar_pronosticos()
const filas = $input.all().map(({ json: x }) => ({
  usuario_id: x.usuario_id,
  proxima_lluvia: x.proxima_lluvia,
  probabilidad: x.probabilidad,
  mm: x.mm,
  horizonte_hasta: x.horizonte_hasta,
  fuente: x.fuente,
  error: x.error,
}));
return [{ json: { total: filas.length, datos: JSON.stringify(filas) } }];

const r = $('Unir resultado').all().map((i) => i.json);
const fallidos = r.filter((x) => x.error);
return [{ json: {
  nivel: fallidos.length ? (fallidos.length === r.length ? 'error' : 'aviso') : 'info',
  mensaje: `Alertas de lluvia: ${r.length - fallidos.length} enviadas, ${fallidos.length} con error`,
  datos: JSON.stringify({ enviadas: r.length - fallidos.length, errores: fallidos.map((x) => ({ usuario_id: x.usuario_id, error: x.error })) }),
} }];

// Resumen de las consultas de pronóstico (para bot_clima.logs): grupos consultados y errores
const grupos = $('Agrupar por zona').all();
const errores = [];
$input.all().forEach((item, i) => {
  const g = grupos[i]?.json;
  const r = item.json;
  const sinDatos = g?.fuente === 'open-meteo' ? !r?.hourly : !Array.isArray(r?.data);
  if (r?.error || sinDatos) {
    errores.push({ grupo: g?.grupo, usuarios: g?.usuarios?.length, error: r?.error?.message || r?.error || 'Respuesta sin datos de pronóstico' });
  }
});
return [{
  json: {
    nivel: errores.length ? 'error' : 'info',
    mensaje: errores.length
      ? `Pronóstico: ${errores.length} de ${grupos.length} consultas fallaron`
      : `Pronóstico consultado para ${grupos.length} grupo(s)`,
    datos: JSON.stringify({ grupos: grupos.length, errores }),
  },
}];
